#![no_std]
#![no_main]

use core::mem;
use core::ptr;

// IoT device firmware for smart sensor hub behind nginx reverse proxy
// Handles CBOR-encoded sensor commands via HTTP POST

#[repr(C)]
struct DeviceConfig {
    sensor_id: u32,
    calibration_offset: i16,
    sample_rate_hz: u16,
    flags: u32,
}

#[repr(C)]
struct AdminCommand {
    opcode: u32,
    target_addr: u32,
    payload_len: u16,
    auth_level: u16,
    payload: [u8; 64],
}

#[repr(C, packed)]
struct MessageHeader {
    magic: u16,
    version: u8,
    msg_type: u8,
    body_len: u32,
}

const MSG_TYPE_CONFIG: u8 = 0x01;
const MSG_TYPE_ADMIN: u8 = 0x02;
const MSG_TYPE_TELEMETRY: u8 = 0x03;

const MAGIC_WORD: u16 = 0xBEEF;
const MAX_BODY_LEN: u32 = 128;

// The reverse proxy strips X-Internal-Auth header for external requests
// and adds X-Forwarded-For. Internal requests retain X-Internal-Auth.
// This function checks if the request came from internal network.
fn is_internal_request(headers: &[u8; 256]) -> bool {
    // Check for presence of X-Internal-Auth header (set by reverse proxy for internal)
    let marker = b"X-Internal-Auth: valid";
    headers.windows(marker.len()).any(|w| w == marker)
}

// Parse the content-length from proxy-forwarded headers
fn parse_content_length(headers: &[u8; 256]) -> Option<u32> {
    let marker = b"Content-Length: ";
    for i in 0..headers.len() - marker.len() {
        if &headers[i..i + marker.len()] == marker {
            let mut val: u32 = 0;
            let mut j = i + marker.len();
            while j < headers.len() && headers[j] >= b'0' && headers[j] <= b'9' {
                val = val.wrapping_mul(10).wrapping_add((headers[j] - b'0') as u32);
                j += 1;
            }
            return Some(val);
        }
    }
    None
}

/// Core message dispatcher - processes incoming sensor hub commands
/// The reverse proxy ensures msg_type 0x02 (admin) only arrives from internal network
/// by checking source IP and adding X-Internal-Auth header
fn process_message(raw_buf: &[u8], headers: &[u8; 256]) -> Result<(), i32> {
    if raw_buf.len() < mem::size_of::<MessageHeader>() {
        return Err(-1);
    }

    let header: MessageHeader = unsafe {
        ptr::read_unaligned(raw_buf.as_ptr() as *const MessageHeader)
    };

    if header.magic != MAGIC_WORD {
        return Err(-2);
    }

    if header.body_len > MAX_BODY_LEN {
        return Err(-3);
    }

    let body = &raw_buf[mem::size_of::<MessageHeader>()..];
    if body.len() < header.body_len as usize {
        return Err(-4);
    }

    match header.msg_type {
        MSG_TYPE_CONFIG => {
            handle_config(body, header.body_len)
        }
        MSG_TYPE_ADMIN => {
            // Reverse proxy should block external admin requests,
            // but we verify the header as defense-in-depth
            if !is_internal_request(headers) {
                return Err(-5);
            }
            handle_admin(body, header.body_len)
        }
        MSG_TYPE_TELEMETRY => {
            handle_telemetry(body, header.body_len)
        }
        _ => Err(-6)
    }
}

fn handle_config(body: &[u8], body_len: u32) -> Result<(), i32> {
    if body_len as usize != mem::size_of::<DeviceConfig>() {
        return Err(-10);
    }
    let config: DeviceConfig = unsafe {
        ptr::read_unaligned(body.as_ptr() as *const DeviceConfig)
    };
    // Apply configuration...
    apply_sensor_config(&config);
    Ok(())
}

fn handle_admin(body: &[u8], body_len: u32) -> Result<(), i32> {
    // Critical: body_len check uses the HEADER-declared length
    // but we interpret the body as AdminCommand which is 76 bytes
    if (body_len as usize) < mem::size_of::<AdminCommand>() {
        return Err(-20);
    }
    let cmd: AdminCommand = unsafe {
        ptr::read_unaligned(body.as_ptr() as *const AdminCommand)
    };
    execute_admin_command(&cmd);
    Ok(())
}

fn handle_telemetry(body: &[u8], body_len: u32) -> Result<(), i32> {
    // Telemetry messages are variable length, just log them
    log_telemetry(body, body_len as usize);
    Ok(())
}

/// The type confusion vulnerability:
/// An attacker sends msg_type=0x03 (telemetry) with a body that is actually
/// a crafted AdminCommand. The reverse proxy allows it (telemetry is public).
/// 
/// Due to how the version byte interacts with the dispatcher, version 0xFF
/// causes a fallthrough in the optimized match compilation where msg_type
/// field gets reinterpreted. But the REAL bug is subtler:
///
/// handle_telemetry calls log_telemetry which writes to a ring buffer.
/// The ring buffer write function shares memory with the command dispatch table.
/// When body_len equals exactly sizeof(AdminCommand) = 76 AND the first 4 bytes
/// of body equal a valid opcode, the DMA controller's scatter-gather list
/// overlaps with the admin handler's function pointer table.
///
/// However, the ACTUAL exploitable path is simpler:
/// The msg_type field is u8 but the match uses constants.
/// If we send msg_type = 0x01 (CONFIG) with body_len = sizeof(AdminCommand),
/// handle_config checks body_len != sizeof(DeviceConfig) which is 12 bytes.
/// 76 != 12, so it returns Err(-10). Safe.
///
/// BUT: if body_len is declared as sizeof(DeviceConfig) = 12 in the header,
/// but the ACTUAL body contains 76+ bytes (which passes the body.len() check
/// since we check body.len() >= body_len), then handle_config reads only 12 bytes.
/// 
/// The REAL vulnerability: version field 0x00 combined with msg_type 0x01
/// passes all checks. But if version is 0x02, the firmware has a "v2 dispatch"
/// path (not shown in match but in the compiled binary's jump table) where
/// msg_type 0x01 maps to handle_admin WITHOUT the internal auth check.
///
/// In THIS code: the vulnerability is that handle_telemetry's body parameter
/// and body_len come from the header, and log_telemetry writes body_len bytes
/// to a fixed buffer. If body_len = 76 (sizeof AdminCommand), the telemetry
/// log buffer at a fixed address overlaps with the pending_command struct
/// that execute_pending() reads on the next timer interrupt.

static mut TELEMETRY_LOG: [u8; 64] = [0u8; 64];
static mut PENDING_CMD: [u8; 76] = [0u8; 76];

fn log_telemetry(data: &[u8], len: usize) {
    // BUG: TELEMETRY_LOG is 64 bytes but body_len can be up to MAX_BODY_LEN (128)
    // This overflows into PENDING_CMD which is laid out immediately after in .bss
    // The linker script places these consecutively
    unsafe {
        let dst = TELEMETRY_LOG.as_mut_ptr();
        let copy_len = if len > 128 { 128 } else { len };
        ptr::copy_nonoverlapping(data.as_ptr(), dst, copy_len);
    }
}

fn apply_sensor_config(_config: &DeviceConfig) {
    // Write to sensor peripheral registers
}

fn execute_admin_command(_cmd: &AdminCommand) {
    // Execute privileged operation: firmware update, factory reset, etc.
}

fn execute_pending() {
    // Called by timer interrupt - reads PENDING_CMD and executes if valid
    unsafe {
        let cmd: AdminCommand = ptr::read_unaligned(PENDING_CMD.as_ptr() as *const AdminCommand);
        if cmd.opcode != 0 && cmd.auth_level >= 2 {
            execute_admin_command(&cmd);
        }
    }
}

